import flagPlacesData from "@/data/flag-places.json";
import type { FlagPlace } from "@/types/country";

// Lightweight client-safe module: only flag-places.json (~9 KB, generated by
// scripts/build-flag-places.mjs). The leaderboard flag picker ships it with the page.
export const flagPlaces: readonly FlagPlace[] = flagPlacesData;

const byIso3 = new Map(flagPlaces.map((place) => [place.iso3, place]));
const byIso2 = new Map(flagPlaces.map((place) => [place.iso2, place]));

export function flagPlaceByIso3(iso3: string | null | undefined): FlagPlace | undefined {
  return iso3 ? byIso3.get(iso3) : undefined;
}

export function flagPlaceByIso2(iso2: string | null | undefined): FlagPlace | undefined {
  return iso2 ? byIso2.get(iso2.toUpperCase()) : undefined;
}
